\ir _helpers/auth_session.sql
begin;
truncate public.evocash_price_versions,public.evocash_pricing_state,public.evocash_price_audit,public.evocash_purchase_quotes restart identity cascade;
insert into public.evocash_pricing_state default values;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values('e1000000-0000-0000-0000-000000000001','authenticated','authenticated','pricing-admin@example.invalid','x',now(),'{}','{}',now(),now()),
('e1000000-0000-0000-0000-000000000002','authenticated','authenticated','pricing-buyer@example.invalid','x',now(),'{}','{}',now(),now()),
('e1000000-0000-0000-0000-000000000003','authenticated','authenticated','pricing-other@example.invalid','x',now(),'{}','{}',now(),now());
update public.users set role='superadmin' where id='e1000000-0000-0000-0000-000000000001';
-- Test-only prices; no seed price is shipped by the migration.
create temp table cfg(value jsonb);
insert into cfg values('{"unitPriceCentavos":"10","minimumUnitPriceCentavos":"1","minQuantity":"1","maxQuantity":"1000","dailyQuantityLimit":"2000","totalQuantityLimit":"10000","quoteTtlSeconds":"300","largeChangeThresholdBps":"2000"}');
create temp table baseline as select (select count(*) from public.cash_purchases) purchases,
(select count(*) from public.economy_transactions) ledger,(select coalesce(sum(cash_balance),0) from public.wallets) balance;
create temp table results(name text primary key,value jsonb);
grant select on cfg to authenticated;
grant select,insert on results to authenticated;
select ok(not has_function_privilege('anon','public.create_evocash_purchase_quote(text,uuid)','execute'),'anon cannot quote');
select ok(not has_table_privilege('authenticated','public.evocash_price_versions','select'),'administrative price table is not readable directly');
select ok(not has_table_privilege('service_role','public.evocash_price_versions','insert'),'service-role cannot publish through direct insert');
select ok(not has_function_privilege('authenticated','private.evocash_validate_price(jsonb)','execute'),'internal helper is not executable by clients');
select pg_temp.set_test_user('e1000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.admin_get_evocash_pricing()$$,'42501','PERMISSION_DENIED','buyer cannot inspect administration');
select throws_ok($$select public.create_evocash_purchase_quote('1','e2000000-0000-0000-0000-000000000001')$$,'EVOCASH_QUOTES_PAUSED','quoting starts paused');
reset role;
select pg_temp.set_test_user('e1000000-0000-0000-0000-000000000001',true);
set local role authenticated;
select is(public.admin_get_evocash_pricing()->>'current',null,'migration invents no initial price');
select throws_ok($$select public.admin_publish_evocash_price((select value from cfg),null,0,'e2000000-0000-0000-0000-000000000002','Initial test price')$$,'42501','RECENT_AUTH_REQUIRED','fresh JWT without AMR cannot publish');
reset role;
select set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from now()-interval '1 hour')::bigint),jsonb_build_object('method','token_refresh','timestamp',extract(epoch from now())::bigint))))::text,true);
set local role authenticated;
select throws_ok($$select public.admin_publish_evocash_price((select value from cfg),null,0,'e2000000-0000-0000-0000-000000000002','Initial test price')$$,'42501','RECENT_AUTH_REQUIRED','refreshing an old login does not reauthenticate');
reset role;
select set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp','invalid'))))::text,true);
set local role authenticated;
select throws_ok($$select public.admin_publish_evocash_price((select value from cfg),null,0,'e2000000-0000-0000-0000-000000000002','Initial test price')$$,'42501','RECENT_AUTH_REQUIRED','malformed AMR fails closed without a cast error');
reset role;
select set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from now())::bigint))))::text,true);
set local role authenticated;
select throws_ok($$select public.admin_preview_evocash_price(jsonb_set((select value from cfg),'{unitPriceCentavos}','"1.5"'),array['1'],0)$$,'INVALID_PRICE_CONFIG','fractional cents rejected');
select throws_ok($$select public.admin_preview_evocash_price(jsonb_set((select value from cfg),'{unitPriceCentavos}','"9999999999"'),array['1'],0)$$,'INVALID_PRICE_CONFIG','overflow/provider ceiling rejected');
select throws_ok($$select public.admin_preview_evocash_price((select value from cfg),array['0'],0)$$,'INVALID_QUANTITY','zero quantity rejected');
select throws_ok($$select public.admin_preview_evocash_price((select value from cfg),array['-1'],0)$$,'INVALID_QUANTITY','negative quantity rejected');
select throws_ok($$select public.admin_preview_evocash_price((select value from cfg),array['1.5'],0)$$,'INVALID_QUANTITY','fractional quantity rejected');
select throws_ok($$select public.admin_preview_evocash_price((select value from cfg),array['999999999999999999999999'],0)$$,'INVALID_QUANTITY','oversized integer rejected before cast');
select throws_ok($$select public.admin_preview_evocash_price(jsonb_set((select value from cfg),'{unitPriceCentavos}','10'),array['1'],0)$$,'INVALID_PRICE_CONFIG','numeric JSON is not coerced into a financial string');
select throws_ok($$select public.admin_preview_evocash_price(jsonb_set((select value from cfg),'{unitPriceCentavos}','"0"'),array['1'],0)$$,'INVALID_PRICE_CONFIG','zero price rejected');
select throws_ok($$select public.admin_preview_evocash_price((select value from cfg)||'{"extra":"1"}',array['1'],0)$$,'INVALID_PRICE_CONFIG','unknown config keys rejected');
select is(public.admin_preview_evocash_price((select value from cfg),array['1','1000'],0)->'samples'->1->>'totalCentavos','10000','server simulation returns exact integer strings');
insert into results values('published',public.admin_publish_evocash_price((select value from cfg),null,0,'e2000000-0000-0000-0000-000000000002','Initial test price'));
select is(public.admin_publish_evocash_price((select value from cfg),null,0,'e2000000-0000-0000-0000-000000000002','Initial test price'),(select value from results where name='published'),'publication replay returns exact original result despite stale revision');
select throws_ok($$select public.admin_publish_evocash_price((select value from cfg),null,1,'e2000000-0000-0000-0000-000000000002','Different test reason')$$,'IDEMPOTENCY_CONFLICT','same key cannot carry another payload');
select throws_ok($$select public.admin_publish_evocash_price((select value from cfg),null,0,'e2000000-0000-0000-0000-000000000003','Stale price attempt')$$,'PRICE_REVISION_CONFLICT','stale publication rejected');
select is(public.admin_get_evocash_pricing()->>'quotingEnabled','false','publishing never enables quoting');
select is(jsonb_array_length(public.admin_list_evocash_prices(null,1)->'items'),1,'history is paginated');
select is(public.admin_list_evocash_prices(1,20)->'items','[]'::jsonb,'history cursor excludes returned version');
select throws_ok($$select public.admin_publish_evocash_price(jsonb_set((select value from cfg),'{unitPriceCentavos}','"15"'),null,1,'e2000000-0000-0000-0000-000000000003','Large test change')$$,'ADDITIONAL_CONFIRMATION_REQUIRED','old version threshold protects large changes');
reset role;
update public.evocash_pricing_state set quoting_enabled=true where id; -- local test fixture only
select pg_temp.set_test_user('e1000000-0000-0000-0000-000000000002',true);
set local role authenticated;
insert into results values('quote',public.create_evocash_purchase_quote('25','e2000000-0000-0000-0000-000000000004'));
select is((select value->>'totalCentavos' from results where name='quote'),'250','quote freezes exact total');
select is(public.create_evocash_purchase_quote('25','e2000000-0000-0000-0000-000000000004'),(select value from results where name='quote'),'quote retry is idempotent');
select throws_ok($$select public.create_evocash_purchase_quote('26','e2000000-0000-0000-0000-000000000004')$$,'IDEMPOTENCY_CONFLICT','quote retry cannot change quantity');
select is((select count(*)::integer from public.evocash_purchase_quotes),1,'owner sees own quote');
select throws_ok($$select public.create_evocash_purchase_quote('1001','e2000000-0000-0000-0000-000000000099')$$,'INVALID_QUANTITY','quote enforces configured maximum');
select lives_ok($$do $rate$ begin for i in 1..9 loop perform public.create_evocash_purchase_quote('1',gen_random_uuid()); end loop; end $rate$;$$,'bounded quote requests succeed');
select throws_ok($$select public.create_evocash_purchase_quote('1','e2000000-0000-0000-0000-000000000098')$$,'QUOTE_RATE_LIMIT','eleventh new quote in a minute is rate limited');
select is(public.create_evocash_purchase_quote('25','e2000000-0000-0000-0000-000000000004'),(select value from results where name='quote'),'idempotent replay does not consume rate budget');

select throws_ok($$delete from public.evocash_purchase_quotes$$,'42501',null,'owner cannot delete quotes');
reset role;
insert into public.evocash_purchase_quotes(user_id,request_id,quantity,unit_price_centavos,total_centavos,price_version_id,created_at,expires_at)
select 'e1000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000097',1,10,10,id,now()-interval '10 minutes',now()-interval '5 minutes' from public.evocash_price_versions limit 1;
set local role authenticated;
select throws_ok($$select public.create_evocash_purchase_quote('1','e2000000-0000-0000-0000-000000000097')$$,'QUOTE_EXPIRED','expired quote retry cannot silently issue a new quote');
reset role;
select pg_temp.set_test_user('e1000000-0000-0000-0000-000000000003',true);
set local role authenticated;
select is((select count(*)::integer from public.evocash_purchase_quotes),0,'other user cannot read another quote');
reset role;
select pg_temp.set_test_user('e1000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from now())::bigint))))::text,true);
set local role authenticated;
select lives_ok($$select public.admin_publish_evocash_price(jsonb_set((select value from cfg),'{unitPriceCentavos}','"15"'),null,1,'e2000000-0000-0000-0000-000000000003','Large test change',true)$$,'large change accepts explicit additional confirmation');
reset role;
select is((select total_centavos::text from public.evocash_purchase_quotes where request_id='e2000000-0000-0000-0000-000000000004'),'250','new price never rewrites old quote');
select throws_ok($$update public.evocash_price_versions set reason='overwrite'$$,'42501','EVOCASH_HISTORY_IMMUTABLE','even owner cannot update historical price');
select throws_ok($$delete from public.evocash_price_audit$$,'42501','EVOCASH_HISTORY_IMMUTABLE','audit is append only');
select throws_ok($$update public.evocash_purchase_quotes set total_centavos=1$$,'42501','EVOCASH_HISTORY_IMMUTABLE','quote snapshot is immutable');
set local role authenticated;
select lives_ok($$select public.admin_publish_evocash_price(jsonb_set((select value from cfg),'{unitPriceCentavos}','"15"'),clock_timestamp()+interval '1 day',2,'e2000000-0000-0000-0000-000000000005','Scheduled test price')$$,'future price can be scheduled');
select is(public.admin_get_evocash_pricing()->'current'->>'revision','2','scheduled price is not effective early');
select is(public.admin_get_evocash_pricing()->'latest'->>'revision','3','scheduled latest version is explicit');
select throws_ok($$select public.admin_publish_evocash_price(jsonb_set((select value from cfg),'{unitPriceCentavos}','"15"'),null,3,'e2000000-0000-0000-0000-000000000006','Out of order price')$$,'PRICE_START_CONFLICT','scheduled sequence cannot overlap or reorder');
select lives_ok($$select public.admin_pause_evocash_quotes(3,'e2000000-0000-0000-0000-000000000007','Emergency test pause')$$,'admin can pause quotes independently of prices');
select is(public.admin_pause_evocash_quotes(3,'e2000000-0000-0000-0000-000000000007','Emergency test pause')->>'revision','4','pause replay does not append twice');
reset role;
select pg_temp.set_test_user('e1000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.create_evocash_purchase_quote('1','e2000000-0000-0000-0000-000000000008')$$,'EVOCASH_QUOTES_PAUSED','emergency pause stops new quotes');
reset role;
select pg_temp.revoke_test_session('e1000000-0000-0000-0000-000000000002');
set local role authenticated;
select is((select count(*)::integer from public.evocash_purchase_quotes),0,'revoked owner session loses quote access');
select throws_ok($$select public.create_evocash_purchase_quote('1','e2000000-0000-0000-0000-000000000008')$$,'42501','PERMISSION_DENIED','revoked session cannot quote');
reset role;
select is((select count(*) from public.cash_purchases),(select purchases from baseline),'pricing never changes purchases');
select is((select count(*) from public.economy_transactions),(select ledger from baseline),'pricing never changes ledger');
select is((select coalesce(sum(cash_balance),0) from public.wallets),(select balance from baseline),'pricing never changes cash balance');
select is((select count(*)::integer from public.evocash_price_audit),4,'each accepted mutation has exactly one audit event');
select pg_temp.set_test_user('e1000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from now())::bigint))))::text,true);
insert into public.evocash_price_audit(actor_user_id,action,price_version_id,applied_revision,request_id,request_payload,reason)
select 'e1000000-0000-0000-0000-000000000001','publish',(select latest_version_id from public.evocash_pricing_state),1000+i,gen_random_uuid(),'{}','Synthetic rate fixture' from generate_series(1,7) i;
set local role authenticated;
select throws_ok($$select public.admin_publish_evocash_price((select value from cfg),clock_timestamp()+interval '2 days',4,'e2000000-0000-0000-0000-000000000096','Rate limited test price',true)$$,'PRICE_RATE_LIMIT','publication rate limit is enforced in backend');
reset role;
select * from finish();
rollback;
